import React, { Component } from 'react'
import { connect } from 'react-redux'
import { injectIntl } from 'react-intl'
import { Row, Col, Form, Button, notification, Input, DatePicker, Icon, Alert, InputNumber } from 'antd'
import IntlMessages from '../../../../../components/utility/intlMessages'
import policyAction from '../../../../../redux/policy/actions'
import CircularLoader from '../../../../../components/CircularLoader'
import moment from 'moment'
import queryString from 'query-string'
import { ContainerLayout, ContainerBody } from './index.style'
import validator from '../../../../../helpers/validator'
import { get, size } from 'lodash'
import { errorHandler } from '../../../../../components/utility/formItems'
import {
  multipleFieldCheck,
  finalValues,
  momentFieldValues
} from './fieldCheck'
import EndorseWelcome from '../GoVietHotelStayProtectionThankYou'
import { ERROR_STRINGS } from '../../../../../constants/lang'

const { resetReduxPolicy, tokenizedDetailEndorsement, tokenizedEndorsement } = policyAction

class GoVietHotelStayProtectionContainer extends Component {
  constructor (props) {
    super(props)
    this.state = {
      insuredName: [],
      internalID: '',
      token: '',
      buttonDisabled: true
    }
  }

  componentDidMount () {
    const { id } = this.props
    const internalId = get(id, 'match.params.id')
    const tokenObject = get(id, 'location.search', '')
    if (tokenObject) {
      const token = get(queryString.parse(tokenObject), 'token', '')
      if (token && internalId) {
        this.setState({
          internalId: internalId,
          token: token
        })
        this.props.tokenizedDetailEndorsement({
          query: {
            id: internalId,
            token: token
          }
        })
      }
    }
  }

  componentWillReceiveProps (nextProps) {
    const { insuredName } = this.state
    const { policyEndorsementError, policyEndorsement, policyEndorsementMessage, getPolicyEndorsementDetailResult } = nextProps
    if (size(getPolicyEndorsementDetailResult) > 0 && insuredName.length === 0) {
      const insuredNames = get(getPolicyEndorsementDetailResult, 'Request.insured_names', [])
      if (insuredNames.length > 0) {
        this.setState({
          insuredName: insuredNames.map((item, index) => {
            return {
              id: index + 1,
              value: item,
              addButtonShow: true,
              deleteButtonShow: true
            }
          })
        })
      } else {
        this.setState({
          insuredName: [{ id: 1, value: '', addButtonShow: true, deleteButtonShow: false }]
        })
      }
    }
    if (policyEndorsementMessage !== '' && policyEndorsementMessage !== 'success') {
      const errorData = momentFieldValues(get(policyEndorsement, 'error', ''))
      errorHandler.call(this, {
        submitError: policyEndorsementError,
        detailMessage: errorData,
        resetFunction: () => this.props.resetReduxPolicy(['tokenisedEndorsementDataMessage'])
      })
    }
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error) => {
        resolve(!error)
      })
    })
  }

  showErrorMessage = () => {
    return <Alert
      message={<IntlMessages id={ERROR_STRINGS.error} />}
      description={<IntlMessages id={ERROR_STRINGS.serverError} />}
      type='error'
    />
  }

  componentDidUpdate (nextProps, nextState) {
    const { buttonDisabled, insuredName } = nextState
    const { form } = nextProps
    if (buttonDisabled) {
      const formBody = form.getFieldsValue()
      const checkIn = get(formBody, 'check_in_time')
      const checkOut = get(formBody, 'check_out_time')
      const room = get(formBody, 'number_of_rooms')
      const multipleFieldsCheck = multipleFieldCheck(insuredName)

      if (!multipleFieldsCheck || room || checkIn || checkOut) {
        this.setState({
          buttonDisabled: false
        })
      }
    }
  }

  finalSubmit = async (e) => {
    e.preventDefault()
    const { internalId, token, insuredName } = this.state
    const { form } = this.props
    const formBody = form.getFieldsValue()
    const checkIn = get(formBody, 'check_in_time')
    const checkOut = get(formBody, 'check_out_time')
    const room = get(formBody, 'number_of_rooms')
    const multipleFieldsCheck = multipleFieldCheck(insuredName)

    if (checkIn && !checkOut) {
      this.props.form.setFields({
        check_out_time: {
          value: '',
          errors: [new Error(this.intlText({ id: 'Waktu check-out baru tidak boleh kosong' }))]
        }
      })
      return
    }
    if (!checkIn && checkOut) {
      this.props.form.setFields({
        check_in_time: {
          value: '',
          errors: [new Error(this.intlText({ id: 'Waktu check-in baru tidak boleh kosong' }))]
        }
      })
      return
    }
    if (checkIn && checkOut) {
      const checkInTime = moment(get(formBody, 'check_in_time')).format('YYYY-MM-DD HH:mm:ss')
      const checkOutTime = moment(get(formBody, 'check_out_time')).format('YYYY-MM-DD HH:mm:ss')
      if (checkInTime && checkOutTime) {
        const dateDiff = moment.duration(moment(checkOutTime).diff(moment(checkInTime))) > 0
        if (!dateDiff) {
          this.props.form.setFields({
            check_in_time: {
              value: get(formBody, 'check_in_time'),
              errors: [new Error(this.intlText({ id: 'Tanggal checkin lebih besar dari tanggal checkout' }))]
            },
            check_out_time: {
              value: get(formBody, 'check_out_time'),
              errors: [new Error(this.intlText({ id: 'Tanggal checkin lebih besar dari tanggal checkout' }))]
            }
          })
        }
      }
    }
    if (room && multipleFieldsCheck) {
      notification.error({
        message: this.intlText({ id: 'Name tertanggung tambahan tidak boleh kosong' })
      })
      return
    }
    // if (!!room && !multipleFieldsCheck) {
    //   this.props.form.setFields({
    //     number_of_rooms: {
    //       value: '',
    //       errors: [new Error(this.intlText({ id: 'Jumlah kamar tambahan tidak boleh kosong' }))]
    //     }
    //   })
    //   return
    // }

    const payload = {
      ...formBody,
      check_in_time: get(formBody, 'check_in_time', '') ? moment(get(formBody, 'check_in_time', '')).format('YYYY-MM-DD HH:mm:ss') : '',
      check_out_time: get(formBody, 'check_out_time', '') ? moment(get(formBody, 'check_out_time', '')).format('YYYY-MM-DD HH:mm:ss') : '',
      insured_names: finalValues(insuredName),
      number_of_rooms: get(formBody, 'number_of_rooms') ? get(formBody, 'number_of_rooms') : 0
    }
    this.props.tokenizedEndorsement({
      query: {
        internal_id: internalId,
        token: token
      },
      body: payload
    })
  }
  addInsuredName = () => {
    const lastItem = this.state.insuredName[this.state.insuredName.length - 1]
    const lastItemId = get(lastItem, 'id')
    const modifiedData = [...this.state.insuredName, {
      id: lastItemId + 1, value: '', addButtonShow: true, deleteButtonShow: true
    }]
    this.setState({
      insuredName: modifiedData.map((item) => {
        return {
          ...item,
          deleteButtonShow: true
        }
      })
    })
  }

  removedInsuredName = (id) => {
    const insuredData = this.state.insuredName.filter(item => item.id !== id)
    const finalData = insuredData.length === 1 ? insuredData.map((item) => {
      return {
        ...item,
        deleteButtonShow: false
      }
    }) : insuredData
    this.setState({
      insuredName: finalData
    })
  }
  onChangeInputField = (e, id) => {
    this.setState({
      insuredName: this.state.insuredName.map((item) => {
        if (item.id === id) {
          return {
            ...item,
            value: e.target.value
          }
        }
        return item
      })
    })
  }

  render () {
    const { getPolicyEndorsementDetailResult, policyEndorsementDetailLoading, form, policyEndorsementDetailError, policyEndorsementLoading, policyEndorsementMessage } = this.props
    const { getFieldDecorator } = form
    const { insuredName, buttonDisabled } = this.state
    const isSuccessFulEndorse = (policyEndorsementMessage === 'success') || get(getPolicyEndorsementDetailResult, 'EndorsementStatus') === 'SUCCESS'
    return (
      <ContainerLayout>
        {
          isSuccessFulEndorse ? <EndorseWelcome /> : policyEndorsementDetailError ? this.showErrorMessage()
            : <CircularLoader isSpining={policyEndorsementDetailLoading || policyEndorsementLoading}>
              <ContainerBody>
                <h3 className='form-heading'><b><IntlMessages id='Hotel Stay Protection Endorsement Form' /></b></h3>
                <p className='form-subheading'><IntlMessages id='Lengkapi form ini untuk melakukan endorsement kepada polis dibawah' /></p>
                <Form onSubmit={this.finalSubmit}>
                  <Row type='flex'>
                    <Col span={24}>
                      <p><IntlMessages id='Booking id' />: {get(getPolicyEndorsementDetailResult, 'Request.reference_id')}</p>
                      <p><IntlMessages id='Nomor polis' />: {get(getPolicyEndorsementDetailResult, 'InsurancePolicyNo')}</p>
                    </Col>
                    <Col span={24}>
                      <p><b><IntlMessages id='Waktu check-in baru' /></b></p>
                      <Form.Item>
                        {
                          getFieldDecorator('check_in_time', {
                            rules: [
                              {
                                type: 'object'
                              }
                            ]
                          })(<DatePicker
                            showTime
                            format='YYYY-MM-DD HH:mm:ss'
                            placeholder={this.intlText({ id: 'Tanggal' })}
                          />)
                        }
                      </Form.Item>
                    </Col>
                    <Col span={24}>
                      <p><b><IntlMessages id='Waktu check-out baru' /></b></p>
                      <Form.Item>
                        {
                          getFieldDecorator('check_out_time', {
                            rules: [
                              {
                                type: 'object'
                              }
                            ]
                          })(<DatePicker
                            showTime
                            format='YYYY-MM-DD HH:mm:ss'
                            placeholder={this.intlText({ id: 'Tanggal' })}
                          />)
                        }
                      </Form.Item>
                    </Col>
                    <Col span={16}>
                      <p><b><IntlMessages id='Nama tertanggung tambahan' /></b></p>
                      {
                        insuredName.map((item, index) => {
                          return (
                            <div className='additional__insured_name' key={index}>
                              <Input value={item.value} onChange={(e) => this.onChangeInputField(e, item.id)} />
                              <div className='button__section'>
                                {
                                  item.addButtonShow &&
                                  <Icon className='button__plus' type='plus-circle' theme='filled' onClick={this.addInsuredName} />
                                }
                                {
                                  item.deleteButtonShow &&
                                  <Icon className='button__minus' type='minus-circle' theme='filled' onClick={() => { this.removedInsuredName(item.id) }} />
                                }
                              </div>
                            </div>
                          )
                        })
                      }
                    </Col>
                    <Col span={12}>
                      <p><b><IntlMessages id='Jumlah kamar tambahan' /></b></p>
                      <Form.Item>
                        {
                          getFieldDecorator('number_of_rooms', {
                            rules: [
                              {
                                validator: validator.checkValidator
                              }
                            ]
                          })(<InputNumber className='input__room_no' placeholder={this.intlText({ id: 'jumlah kamar' })} />)
                        }
                      </Form.Item>
                    </Col>
                    <Col className='button__column' span={24}>
                      <Button disabled={buttonDisabled} className='button__final_submit' htmlType='submit'><IntlMessages id='Kirim' /></Button>
                    </Col>
                  </Row>
                </Form>
              </ContainerBody>
            </CircularLoader>
        }
      </ContainerLayout>
    )
  }
}

GoVietHotelStayProtectionContainer.defaultProps = {
  policyEndorsementLoading: false,
  policyEndorsementError: false,
  policyEndorsementDetailLoading: false,
  policyEndorsementDetailError: false
}
const GoVietHotelStayProtectionContainerWrapped = Form.create()(GoVietHotelStayProtectionContainer)
export default connect(
  state => ({
    getPolicyEndorsementDetailResult: state.Policy.tokenisedEndorsementDetail,
    policyEndorsementDetailLoading: state.Loading.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsementDetailError: state.Error.TOKENIZED_ENDORSEMENT_DETAIL,
    policyEndorsement: state.Policy.tokenisedEndorsementData,
    policyEndorsementMessage: state.Policy.tokenisedEndorsementDataMessage,
    policyEndorsementLoading: state.Loading.TOKENIZED_ENDORSEMENT,
    policyEndorsementError: state.Error.TOKENIZED_ENDORSEMENT
  }),
  {
    resetReduxPolicy, tokenizedDetailEndorsement, tokenizedEndorsement
  }
)(injectIntl(GoVietHotelStayProtectionContainerWrapped))
