import moment from 'moment'

export function multipleFieldCheck (data) {
  let flag = false
  data.forEach(element => {
    if (element.value === '') {
      flag = true
    }
  })
  return flag
}

export function finalValues (data) {
  let array = []
  data.forEach(element => {
    if (element.value) {
      array.push(element.value)
    }
  })
  return array
}

export function momentFieldValues (data) {
  if (data.length > 0) {
    return data.map((item) => {
      return {
        ...item,
        val: moment(item.val)
      }
    })
  }
  return ''
}
